export function getSummaryForDay(day: number): EikenSummaryDay | null {
    return EIKEN1_SUMMARIES.find(e => e.day === day) || null;
}

export function getDateForDay(day: number): Date {
    const d = new Date(START_DATE);
    d.setDate(d.getDate() + day - 1);
    return d;
}

export function getTodayDay(): number {
    const now = new Date();
    const start = new Date(START_DATE);
    const diff = Math.floor((now.getTime() - start.getTime()) / (1000 * 60 * 60 * 24));
    if (diff < 0) return 1;
    if (diff >= TOTAL_DAYS) return TOTAL_DAYS;
    return diff + 1;
}
